import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const yotsurmMagicPhysicalScenarios={'beast-magic-ordinary':'a2-p16-r2c1','beast-magic-dedicated':'a2-p16-r2c1','wolf-magic-ordinary':'a2-p16-r2c2','wolf-magic-dedicated':'a2-p16-r2c2'} as const;
export type YotsurmMagicPhysicalScenario=keyof typeof yotsurmMagicPhysicalScenarios;
export function isYotsurmMagicPhysicalScenario(name:string):name is YotsurmMagicPhysicalScenario{return Object.hasOwn(yotsurmMagicPhysicalScenarios,name);}
export function yotsurmMagicPhysicalMode(name:YotsurmMagicPhysicalScenario){const wolf=name.startsWith('wolf-'),dedicated=name.endsWith('-dedicated');return{card:yotsurmMagicPhysicalScenarios[name],wolf,dedicated,use:wolf?6:4,effect:wolf?6:dedicated?5:4,damage:wolf?12:dedicated?7:5,name:wolf?'餓狼':'妖獣'};}
export function makeYotsurmMagicPhysicalScenario(name:YotsurmMagicPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:'none'|'water'}={}){
 const m=yotsurmMagicPhysicalMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.owner??'餓狼ヨーツルム','白魔術師シェリム','大神官ジル','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.magic_level=20+(options.level??m.use)-gameStats(s,a).magic_level;
 const front=options.follower==='none'?null:takeCard(s,b,options.follower==='water'?'水竜':'守護者'),rear=options.follower===undefined?takeCard(s,b,'天使'):null,metal=options.follower==='none'?null:takeCard(s,c,'メタルゴーレム'),soldier=options.follower==='none'?null:takeCard(s,c,'兵士'),keep=[takeCard(s,a,m.card),takeCard(s,a,'必勝の祈り'),takeCard(s,b,'a2-p06-r1c1'),takeCard(s,b,'a2-p05-r3c1'),takeCard(s,d,'命運凶変'),...[front,rear,metal,soldier].filter((x):x is string=>!!x)];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`YOTSURM_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('YOTSURM_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('YOTSURM_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===b?[front,rear]:p.id===c?[metal,soldier]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
